#[wasm_bindgen]
pub fn normalize(v: &[f32]) -> Vec<f32> {
    let norm: f32 = v.iter().map(|x| x * x).fold(0.0_f32, f32::add).sqrt();
    if norm == 0.0_f32 {
        return v.to_vec();
    }
    v.iter().map(|x| x / norm).collect()
}
